{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 가정폭력피해자 보호시설 입소와 다른 방법으로 반려동물을 돌볼 수 없는 사정이 동물 인수 가능한 사유인지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제18조제1항제4호는 소유자등이 「가정폭력방지 및 피해자보호 등에 관한 법률」 제7조에 따른 가정폭력피해자 보호시설에 입소하는 경우를 인수 가능한 사유로 정하고 있다. 또한 같은 항 본문은 소유자등이 다른 방법으로는 정상적으로 동물을 사육하기 어려워 동물 인수신청서를 제출한 경우 해당 동물을 인수할 수 있다고 규정한다. 따라서 가정폭력피해자 보호시설 입소와 다른 방법으로는 반려동물을 제대로 돌볼 수 없는 사정은 조례상 인수 가능한 사유에 해당한다.",
          "b_ids": "동물보호:제18조제1항,동물보호:제18조제1항제4호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
